use vstd::prelude::*;

verus! {

fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    ensures
        result@.len() == a@.len(),
        forall|i: int| 0 <= i < a@.len() ==> result@[i] == a@[i],
{
    let mut result: Vec<T> = Vec::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a@.len(),
            result@.len() == i as int,
            forall|j: int| 0 <= j < i as int ==> result@[j] == a@[j],
        decreases a.len() - i,
    {
        // Read from input without modifying it, and append to result.
        let x: T = a[i];
        result.push(x);

        i = i + 1;
    }

    result
}

} // verus!

